{"implementation":"def solve(case):
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    if 'attempts' not in case or 'max_attempts' not in case:
        raise ValueError('missing required fields: attempts and max_attempts')
    attempts = case['attempts']
    max_attempts = case['max_attempts']
    if not isinstance(attempts, list):
        raise ValueError('attempts must be a list')
    if not isinstance(max_attempts, int) or max_attempts < 1:
        raise ValueError('max_attempts must be a positive integer')
    for i, att in enumerate(attempts):
        if not isinstance(att, dict):
            raise ValueError(f'attempt {i} is not a dict')
        if 'success' not in att or 'failure_signature' not in att or 'reflection' not in att:
            raise ValueError(f'attempt {i} missing required fields')
        if not isinstance(att['success'], bool):
            raise ValueError(f'attempt {i} success must be bool')
        if not isinstance(att['failure_signature'], str):
            raise ValueError(f'attempt {i} failure_signature must be string')
        if not isinstance(att['reflection'], str):
            raise ValueError(f'attempt {i} reflection must be string')
    n = len(attempts)
    if n == 0:
        return {
            'decision': 'retry',
            'memory_append': None,
            'next_attempt': 1
        }
    last = attempts[-1]
    if last['success']:
        return {
            'decision': 'terminate',
            'memory_append': None,
            'next_attempt': n
        }
    # failure case
    prev_signatures = [a['failure_signature'] for a in attempts[:-1]]
    if last['failure_signature'] in prev_signatures:
        return {
            'decision': 'terminate',
            'memory_append': None,
            'next_attempt': n
        }
    if n >= max_attempts:
        return {
            'decision': 'terminate',
            'memory_append': None,
            'next_attempt': n
        }
    # retry
    if not last['reflection']:
        raise ValueError('reflection must be nonempty for retry')
    return {
        'decision': 'retry',
        'memory_append': {
            'reflection': last['reflection'],
            'signature': last['failure_signature']
        },
        'next_attempt': n + 1
    }
